// Assuming you have a Lighthouse setup, you can reproduce the issue by running a Lighthouse audit on a page with a large DOM size.

// Example code to run Lighthouse programmatically
const lighthouse = require('lighthouse');
const chromeLauncher = require('chrome-launcher');

(async () => {
  const chrome = await chromeLauncher.launch({chromeFlags: ['--headless']});
  const options = {logLevel: 'info', output: 'json', onlyCategories: ['performance'], port: chrome.port};
  const runnerResult = await lighthouse('https://example.com', options);

  // Output the audit results
  const audits = runnerResult.lhr.audits;
  console.log('Avoid an excessive DOM size:', audits['dom-size'].displayValue);

  await chrome.kill();
})();
